import { OpenCode } from "@opencode/client";
import {
  SUPPORTED_OPENCODE_MAJOR,
  TESTED_OPENCODE_VERSION,
  type OpenCodeConnectionState,
} from "../../shared/opencode.ts";
import { nativeEngineStatusSchema, type NativeEngineStatus } from "../../shared/contracts.ts";
import {
  assertAllowedUrl,
  createSafeFetch,
  NetworkPolicyError,
  sanitizeNetworkError,
  validateBaseUrlSyntax,
  type NetworkPolicy,
} from "../security/network.ts";
import { redactText } from "../security/redaction.ts";

export const FREE_DEEPSEEK_MODEL = "opencode/deepseek-v4.1-flash-free" as const;
export const REQUIRED_OPENCODE_MAJOR = SUPPORTED_OPENCODE_MAJOR;

export interface NativeClientOptions {
  baseUrl: string;
  username?: string;
  password?: string;
  mode?: "local" | "hosted-demo" | "private-hosted";
  allowInsecureRemote?: boolean;
  allowedHosts?: string[];
  allowedPorts?: number[];
  allowPrivateNetwork?: boolean;
  requestTimeoutMs?: number;
  maxResponseBytes?: number;
  resolver?: NetworkPolicy["resolver"];
  fetchImpl?: typeof fetch;
}

export interface NativeEngineError extends Error {
  code: "ENGINE_UNAVAILABLE" | "ENGINE_INCOMPATIBLE" | "ENGINE_AUTH" | "MODEL_UNAVAILABLE";
  retryable: boolean;
}

export function engineError(code: NativeEngineError["code"], message: string, retryable: boolean): NativeEngineError {
  const error = new Error(redactText(message)) as NativeEngineError;
  error.name = "NativeEngineError";
  error.code = code;
  error.retryable = retryable;
  return error;
}

export function networkPolicy(options: NativeClientOptions): NetworkPolicy {
  return {
    baseUrl: options.baseUrl,
    allowInsecureRemote: options.allowInsecureRemote,
    allowedHosts: options.allowedHosts,
    allowedPorts: options.allowedPorts,
    allowPrivateNetwork: options.allowPrivateNetwork,
    requestTimeoutMs: options.requestTimeoutMs,
    maxResponseBytes: options.maxResponseBytes,
    resolver: options.resolver,
    fetchImpl: options.fetchImpl,
  };
}

export function createNativeClient(options: NativeClientOptions) {
  const url = validateBaseUrlSyntax(options.baseUrl);
  const authorization = options.password
    ? `Basic ${Buffer.from(`${options.username || "opencode"}:${options.password}`).toString("base64")}`
    : undefined;

  return OpenCode.make({
    baseUrl: url.toString(),
    fetch: createSafeFetch(networkPolicy(options)),
    headers: authorization ? { authorization } : undefined,
  });
}

export class ConnectionConfigError extends Error {
  constructor(
    message: string,
    readonly code: "INVALID_URL" | "REMOTE_HTTP_FORBIDDEN" | "URL_CREDENTIALS_FORBIDDEN" | "UNSUPPORTED_SCHEME",
  ) {
    super(message);
  }
}

export interface ValidatedServerUrl {
  url: string;
  loopback: boolean;
  https: boolean;
}

/**
 * Validates the OpenCode server address accepted by this application.
 *
 * Local deployments may use loopback HTTP because the connection never leaves
 * the machine. Any non-loopback address must use HTTPS; the network policy
 * additionally requires an explicit host allowlist and blocks private and
 * metadata addresses unless separately configured.
 */
export function validateServerUrl(raw: string): ValidatedServerUrl {
  const input = raw.trim();
  if (!input) throw new ConnectionConfigError("Enter an OpenCode server URL.", "INVALID_URL");
  let parsed: URL;
  try {
    parsed = new URL(input);
  } catch {
    throw new ConnectionConfigError("The OpenCode server URL is not a valid absolute URL.", "INVALID_URL");
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new ConnectionConfigError("Only http:// (loopback) and https:// OpenCode URLs are supported.", "UNSUPPORTED_SCHEME");
  }
  if (parsed.username || parsed.password) {
    throw new ConnectionConfigError("Do not put credentials in the server URL. Enter the OpenCode password separately.", "URL_CREDENTIALS_FORBIDDEN");
  }
  if (parsed.search || parsed.hash) {
    throw new ConnectionConfigError("The OpenCode server URL must not include a query string or fragment.", "INVALID_URL");
  }
  const hostname = parsed.hostname.replace(/^\[|\]$/g, "").toLowerCase();
  const loopback = hostname === "localhost" || hostname === "127.0.0.1" || hostname === "::1" || hostname.startsWith("127.");
  if (parsed.protocol === "http:" && !loopback) {
    throw new ConnectionConfigError("A non-loopback OpenCode URL requires HTTPS.", "REMOTE_HTTP_FORBIDDEN");
  }
  parsed.pathname = parsed.pathname.replace(/\/+$/, "");
  return { url: parsed.toString().replace(/\/$/, ""), loopback, https: parsed.protocol === "https:" };
}

export interface VersionCompatibility {
  compatible: boolean;
  major: number | null;
  warning: string | null;
}

export function checkVersionCompatibility(version: string): VersionCompatibility {
  const match = /^(\d+)\.(\d+)\.(\d+)/.exec(version.trim());
  if (!match) {
    return { compatible: false, major: null, warning: "The server did not report a parseable semantic version." };
  }
  const major = Number(match[1]);
  if (major !== SUPPORTED_OPENCODE_MAJOR) {
    return {
      compatible: false,
      major,
      warning: `OpenCode server ${version} is outside the tested major version ${SUPPORTED_OPENCODE_MAJOR}.`,
    };
  }
  if (version.trim() !== TESTED_OPENCODE_VERSION) {
    return {
      compatible: true,
      major,
      warning: `OpenCode server ${version} is a ${SUPPORTED_OPENCODE_MAJOR}.x release, but this build is tested against ${TESTED_OPENCODE_VERSION}. Some capability probes may be unavailable.`,
    };
  }
  return { compatible: true, major, warning: null };
}

export interface ClassifiedFailure {
  code:
    | "AUTH_REQUIRED"
    | "ORIGIN_BLOCKED"
    | "UNAVAILABLE"
    | "TIMEOUT"
    | "MALFORMED"
    | "VERSION_INCOMPATIBLE"
    | "UNKNOWN";
  status: number | null;
  message: string;
  state: OpenCodeConnectionState;
}

function errorStatus(error: unknown): number | null {
  if (!error || typeof error !== "object") return null;
  const candidate = error as { cause?: unknown; status?: unknown; detail?: unknown };
  if (typeof candidate.status === "number") return candidate.status;
  if (candidate.cause && typeof candidate.cause === "object") {
    const nested = candidate.cause as { status?: unknown };
    if (typeof nested.status === "number") return nested.status;
  }
  if (typeof candidate.detail === "string" && /^\d{3}$/.test(candidate.detail)) return Number(candidate.detail);
  return null;
}

function errorTag(error: unknown): string | null {
  return error && typeof error === "object" && typeof (error as { _tag?: unknown })._tag === "string"
    ? (error as { _tag: string })._tag
    : null;
}

function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message;
  if (error && typeof error === "object" && typeof (error as { message?: unknown }).message === "string") {
    return (error as { message: string }).message;
  }
  return String(error);
}

export function classifyConnectionError(error: unknown): ClassifiedFailure {
  const status = errorStatus(error);
  const tag = errorTag(error);
  const raw = errorMessage(error);
  const message = redactSecrets(raw);

  if (status === 401 || tag === "UnauthorizedError" || /authentication required|unauthori[sz]ed|password/i.test(message)) {
    return { code: "AUTH_REQUIRED", status: status ?? 401, message, state: "authentication_required" };
  }
  if (status === 403 || /origin|cors|forbidden|not allowed/i.test(message)) {
    return { code: "ORIGIN_BLOCKED", status: status ?? 403, message, state: "unavailable" };
  }
  if (/ECONNREFUSED|ENOTFOUND|EAI_AGAIN|fetch failed|network|socket|connect/i.test(message)) {
    return { code: "UNAVAILABLE", status, message, state: "unavailable" };
  }
  if (/timed out|timeout|aborted|AbortError/i.test(message)) {
    return { code: "TIMEOUT", status, message, state: "unavailable" };
  }
  if (/malformed|unexpected content|parse|decode/i.test(message)) {
    return { code: "MALFORMED", status, message, state: "unavailable" };
  }
  return { code: "UNKNOWN", status, message, state: "unavailable" };
}

const secretPatterns: Array<[RegExp, string]> = [
  [/(authorization\s*[:=]\s*)(basic|bearer)?\s*[^\s,;]+/gi, "$1[redacted]"],
  [/((?:password|api[_-]?key|access[_-]?token|secret|OPENCODE_PASSWORD|OPENCODE_API_KEY)\s*[:=]\s*)[^\s,;]+/gi, "$1[redacted]"],
  [/(https?:\/\/)([^/@\s]+)@/gi, "$1[redacted]@"],
  [/(Basic|Bearer)\s+[A-Za-z0-9+/=._-]{8,}/g, "$1 [redacted]"],
];

/** Removes credential-shaped values from anything that may be logged or returned. */
export function redactSecrets(value: string): string {
  let redacted = value;
  for (const [pattern, replacement] of secretPatterns) redacted = redacted.replace(pattern, replacement);
  return redacted;
}

export async function probeNativeEngine(options: NativeClientOptions): Promise<NativeEngineStatus> {
  const mode = options.mode ?? "local";
  try {
    const url = validateBaseUrlSyntax(options.baseUrl);
    await assertAllowedUrl(url, networkPolicy(options));
    const client = createNativeClient(options);
    const [server, models] = await Promise.all([
      client.server.info(),
      client.model.list(),
    ]);
    const versionCompatible = new RegExp(`^${REQUIRED_OPENCODE_MAJOR}\\.`).test(server.version);
    const reportedModel = models.data.find((model) => model.enabled !== false) ?? null;
    const modelAvailable = reportedModel !== null;

    return nativeEngineStatusSchema.parse({
      available: true,
      serverVersion: server.version,
      versionCompatible,
      authenticated: true,
      mode,
      model: reportedModel ? `${reportedModel.providerID}/${reportedModel.id}` : null,
      modelAvailable,
      limitation: versionCompatible
        ? modelAvailable
          ? null
          : "OpenCode reported no available model in the native catalog."
        : `OpenCode ${server.version} is not compatible with this build; version ${REQUIRED_OPENCODE_MAJOR}.x is required.`,
    });
  } catch (error) {
    const sanitized = sanitizeNetworkError(error);
    const auth = /401|unauthori[sz]ed|authentication|invalid credentials|forbidden/i.test(sanitized);
    const version = /version|incompatible|404|not found/i.test(sanitized);
    return nativeEngineStatusSchema.parse({
      available: false,
      serverVersion: null,
      versionCompatible: !version,
      authenticated: !auth,
      mode,
      model: null,
      modelAvailable: false,
      limitation: error instanceof NetworkPolicyError
        ? sanitized
        : auth
          ? "OpenCode rejected the configured credentials."
          : version
            ? "OpenCode did not expose a compatible server contract."
            : sanitized || "Native OpenCode is unavailable.",
    });
  }
}

/**
 * Checks reachability, version, and authentication before a native call.
 * Model availability is checked by the selected-model path in the connection
 * service; this function refuses a paid fallback only through that path.
 */
export async function assertEngineReady(options: NativeClientOptions): Promise<NativeEngineStatus> {
  const status = await probeNativeEngine(options);
  if (!status.available) {
    if (!status.authenticated) throw engineError("ENGINE_AUTH", "OpenCode authentication is not ready. Check OPENCODE_PASSWORD and start the server again.", false);
    if (!status.versionCompatible) throw engineError("ENGINE_INCOMPATIBLE", "The OpenCode server version is not compatible with this build.", false);
    throw engineError("ENGINE_UNAVAILABLE", status.limitation ?? "OpenCode is unavailable.", true);
  }
  if (!status.versionCompatible) throw engineError("ENGINE_INCOMPATIBLE", status.limitation ?? "OpenCode version is incompatible.", false);
  return status;
}
import { chmod, mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { z } from "zod";
import {
  connectionStatusSchema,
  type ConnectionStatus,
  type DeploymentMode,
  type DiscoveredModel,
  type OpenCodeDiscovery,
  SUPPORTED_OPENCODE_MAJOR,
  TESTED_OPENCODE_VERSION,
} from "../../shared/opencode.ts";
import type { ModelAccessMode, ModelRef } from "../../shared/workflow.ts";
import {
  checkVersionCompatibility,
  classifyConnectionError,
  ConnectionConfigError,
  createNativeClient,
  redactSecrets,
  validateServerUrl,
  type NativeClientOptions,
} from "./client.ts";
import {
  normalizeDiscovery,
  type RawAgent,
  type RawCommand,
  type RawConfigEntry,
  type RawDiscoveryInput,
  type RawIntegration,
  type RawMcpServer,
  type RawModel,
  type RawPermissionRequest,
  type RawProvider,
  type RawSkill,
} from "./discovery.ts";

export interface NativeClientLike {
  server: { info: () => Promise<{ version: string }> };
  model: { list: () => Promise<{ data: RawModel[] }> };
  provider: { list: () => Promise<{ data: RawProvider[] }> };
  integration: { list: () => Promise<{ data: RawIntegration[] }> };
  agent: { list: () => Promise<{ data: RawAgent[] }> };
  permission: { request: { list: () => Promise<{ data: RawPermissionRequest[] }> } };
  command: { list: () => Promise<{ data: RawCommand[] }> };
  skill: { list: () => Promise<{ data: RawSkill[] }> };
  mcp: { list: () => Promise<{ data: RawMcpServer[] }> };
  config: { get: () => Promise<RawConfigEntry[]> };
}

export interface ConnectionServiceOptions {
  dataDir: string;
  deploymentMode?: DeploymentMode;
  envBaseUrl?: string;
  envUsername?: string;
  envPassword?: string;
  /** Network-policy settings applied to every native request. */
  security?: Omit<NativeClientOptions, "baseUrl" | "username" | "password">;
  clientFactory?: (options: NativeClientOptions) => NativeClientLike;
  now?: () => Date;
}

const settingsSchema = z.object({
  baseUrl: z.string().nullable().default(null),
  authMode: z.enum(["none", "basic"]).default("none"),
  username: z.string().default("opencode"),
  hasPassword: z.boolean().default(false),
  updatedAt: z.string().nullable().default(null),
});

type ConnectionSettings = z.infer<typeof settingsSchema>;

export interface CheckOptions {
  baseUrl?: string;
  username?: string;
  password?: string;
  selected?: ModelRef | null;
  accessMode?: ModelAccessMode;
}

export interface ModelResolution {
  model: DiscoveredModel;
  source: "selected" | "legacy" | "auto-discovery";
}

export class ConnectionService {
  private settings: ConnectionSettings = settingsSchema.parse({});
  private password: string | undefined;
  private cached: ConnectionStatus;
  private discoveryCache: { discovery: OpenCodeDiscovery; expiresAt: number } | null = null;
  private readonly clientFactory: (options: NativeClientOptions) => NativeClientLike;
  private readonly now: () => Date;

  constructor(private readonly options: ConnectionServiceOptions) {
    this.clientFactory = options.clientFactory ?? ((clientOptions) => createNativeClient(clientOptions) as unknown as NativeClientLike);
    this.now = options.now ?? (() => new Date());
    this.password = REDACTED || undefined;
    this.cached = this.initialStatus();
  }

  get deploymentMode(): DeploymentMode {
    return this.options.deploymentMode ?? "local";
  }

  get managed(): boolean {
    return this.deploymentMode !== "local";
  }

  async load(): Promise<void> {
    let stored: Partial<ConnectionSettings> = {};
    try {
      stored = settingsSchema.parse(JSON.parse(await readFile(this.path, "utf8")));
    } catch {
      stored = {};
    }
    const envBase = this.options.envBaseUrl?.trim() || null;
    const baseUrl = this.managed ? envBase : (stored.baseUrl ?? envBase);
    this.settings = settingsSchema.parse({
      baseUrl,
      authMode: stored.authMode ?? (this.password ? "basic" : "none"),
      username: this.options.envUsername?.trim() ?? stored.username ?? "opencode",
      // A server password is memory-only. A persisted "hasPassword" flag from a
      // previous process must not claim the password is still available.
      hasPassword: Boolean(this.password),
      updatedAt: stored.updatedAt ?? null,
    });
    this.cached = this.initialStatus();
  }

  get path(): string {
    return resolve(this.options.dataDir, "connection.json");
  }

  initialStatus(): ConnectionStatus {
    const baseUrl = this.settings.baseUrl ?? this.options.envBaseUrl?.trim() ?? null;
    return connectionStatusSchema.parse({
      state: "not_configured",
      baseUrl,
      deploymentMode: this.deploymentMode,
      managed: this.managed,
      auth: {
        mode: this.settings.authMode,
        username: this.settings.username,
        hasPassword: Boolean(this.password) || this.settings.hasPassword,
      },
      serverVersion: null,
      compatible: null,
      checkedAt: null,
      diagnostics: [],
      discovery: null,
    });
  }

  status(): ConnectionStatus {
    return this.cached;
  }

  /** Creates a client for an authorized session action. Credentials stay in this process. */
  client(): NativeClientLike {
    return this.clientFactory(this.clientOptions());
  }

  /** Current native client options. The password is memory-only and never serialized. */
  clientOptions(): NativeClientOptions {
    const baseUrl = this.settings.baseUrl ?? this.options.envBaseUrl?.trim();
    if (!baseUrl) throw new Error("OpenCode is not configured.");
    return {
      ...this.options.security,
      baseUrl,
      username: this.settings.username,
      password: this.password,
    };
  }

  async refresh(options: { selected?: ModelRef | null; accessMode?: ModelAccessMode } = {}): Promise<ConnectionStatus> {
    return this.check(options);
  }

  async configure(input: { baseUrl: string; username?: string; password?: string }): Promise<ConnectionStatus> {
    if (this.managed) {
      throw new ConnectionConfigError("This deployment manages the OpenCode connection through its environment and secret store.", "INVALID_URL");
    }
    const validated = validateServerUrl(input.baseUrl);
    const password = input.password === undefined ? this.password : input.password;
    this.password = REDACTED || undefined;
    this.settings = settingsSchema.parse({
      baseUrl: validated.url,
      authMode: this.password ? "basic" : "none",
      username: input.username?.trim() || this.settings.username || "opencode",
      hasPassword: Boolean(this.password),
      updatedAt: this.now().toISOString(),
    });
    await this.persist();
    this.discoveryCache = null;
    this.cached = this.initialStatus();
    return this.check({ baseUrl: validated.url, username: this.settings.username, selected: null });
  }

  async reset(): Promise<ConnectionStatus> {
    if (this.managed) throw new ConnectionConfigError("This deployment manages the OpenCode connection through its environment and secret store.", "INVALID_URL");
    this.password = undefined;
    this.discoveryCache = null;
    this.settings = settingsSchema.parse({
      baseUrl: this.options.envBaseUrl?.trim() || null,
      authMode: "none",
      username: this.options.envUsername?.trim() || "opencode",
      hasPassword: false,
      updatedAt: this.now().toISOString(),
    });
    await this.persist();
    this.cached = this.initialStatus();
    return this.cached;
  }

  async check(options: CheckOptions = {}): Promise<ConnectionStatus> {
    const baseUrlInput = options.baseUrl ?? this.settings.baseUrl ?? this.options.envBaseUrl ?? null;
    if (!baseUrlInput) {
      this.cached = this.initialStatus();
      return this.cached;
    }
    let validated;
    try {
      validated = validateServerUrl(baseUrlInput);
    } catch (error) {
      this.cached = this.failureStatus(baseUrlInput, error instanceof Error ? error.message : "Invalid server URL.", [
        {
          code: "INVALID_SERVER_URL",
          severity: "error",
          title: "Invalid OpenCode URL",
          message: error instanceof Error ? error.message : "The URL is invalid.",
          repair: "Use http://127.0.0.1:4096 for local OpenCode, or an https:// URL for a remote server.",
        },
      ]);
      return this.cached;
    }

    const username = options.username?.trim() || this.settings.username || "opencode";
    const password = options.password === undefined ? this.password : options.password.trim();
    if (options.password !== undefined) this.password = password || undefined;
    const client = this.clientFactory({
      ...this.options.security,
      baseUrl: validated.url,
      username,
      password,
    });

    let info: { version: string };
    try {
      info = await client.server.info();
    } catch (error) {
      const failure = classifyConnectionError(error);
      const authCode = failure.code === "AUTH_REQUIRED" && password ? "PASSWORD_MISMATCH" : failure.code;
      this.cached = this.failureStatus(validated.url, failure.message, [{
        code: authCode,
        severity: "error",
        title: failure.state === "authentication_required"
          ? password ? "OpenCode rejected the password" : "REDACTED"
          : "OpenCode is not reachable",
        message: failure.message,
        repair: this.repairFor(authCode),
      }], failure.state);
      this.settings = { ...this.settings, baseUrl: validated.url, username, authMode: password ? "basic" : "none" };
      return this.cached;
    }

    const compatibility = checkVersionCompatibility(info.version);
    if (!compatibility.compatible) {
      this.cached = connectionStatusSchema.parse({
        ...this.initialStatus(),
        state: "incompatible_version",
        baseUrl: validated.url,
        serverVersion: info.version,
        compatible: false,
        checkedAt: this.now().toISOString(),
        diagnostics: [{
          code: "UNSUPPORTED_SERVER_VERSION",
          severity: "error",
          title: "Unsupported OpenCode server version",
          message: compatibility.warning,
          repair: `Install OpenCode ${SUPPORTED_OPENCODE_MAJOR}.x compatible with @opencode/client ${TESTED_OPENCODE_VERSION}, or update Unfinished Business.`,
        }],
      });
      return this.cached;
    }

    const [modelsResult, providersResult, integrationsResult, agentsResult, permissionsResult, commandsResult, skillsResult, mcpResult, configResult] = await Promise.allSettled([
      client.model.list(),
      client.provider.list(),
      client.integration.list(),
      client.agent.list(),
      client.permission.request.list(),
      client.command.list(),
      client.skill.list(),
      client.mcp.list(),
      client.config.get(),
    ]);

    if (modelsResult.status === "rejected" || providersResult.status === "rejected") {
      const failure = classifyConnectionError(modelsResult.status === "rejected" ? modelsResult.reason : providersResult.status === "rejected" ? providersResult.reason : undefined);
      this.cached = this.failureStatus(validated.url, failure.message, [{
        code: failure.code,
        severity: "error",
        title: "OpenCode discovery failed",
        message: failure.message,
        repair: "Confirm the server is healthy and that the account/project can list models. Then retry.",
      }], failure.state);
      return this.cached;
    }

    const raw: RawDiscoveryInput = {
      version: info.version,
      models: modelsResult.value.data,
      providers: providersResult.value.data,
      integrations: integrationsResult.status === "fulfilled" ? integrationsResult.value.data : [],
      agents: agentsResult.status === "fulfilled" ? agentsResult.value.data : [],
      permissions: permissionsResult.status === "fulfilled" ? permissionsResult.value.data : [],
      commands: commandsResult.status === "fulfilled" ? commandsResult.value.data : [],
      skills: skillsResult.status === "fulfilled" ? skillsResult.value.data : [],
      mcpServers: mcpResult.status === "fulfilled" ? mcpResult.value.data : [],
      config: configResult.status === "fulfilled" ? configResult.value : [],
    };
    const discovery = normalizeDiscovery(raw);
    discovery.limitations.push(...this.partialLimitations({
      integrations: integrationsResult.status,
      agents: agentsResult.status,
      permissions: permissionsResult.status,
      commands: commandsResult.status,
      skills: skillsResult.status,
      mcp: mcpResult.status,
      config: configResult.status,
    }));

    const diagnostics = this.diagnosticsFor(discovery, options.selected ?? null, options.accessMode ?? "ALL_ACCESSIBLE");
    const state = diagnostics.some((diagnostic) => diagnostic.severity === "error")
      ? "degraded"
      : diagnosticWarnings(diagnostics) || discovery.server.warning
        ? "degraded"
        : "connected";

    this.discoveryCache = { discovery, expiresAt: Date.now() + 30_000 };
    this.settings = {
      ...this.settings,
      baseUrl: validated.url,
      username,
      authMode: password ? "basic" : "none",
      hasPassword: Boolean(password) || this.settings.hasPassword,
      updatedAt: this.now().toISOString(),
    };
    this.password = password || undefined;
    if (!this.managed) await this.persist();
    this.cached = connectionStatusSchema.parse({
      state,
      baseUrl: validated.url,
      deploymentMode: this.deploymentMode,
      managed: this.managed,
      auth: {
        mode: this.settings.authMode,
        username: this.settings.username,
        hasPassword: Boolean(this.password),
      },
      serverVersion: info.version,
      compatible: true,
      checkedAt: this.now().toISOString(),
      diagnostics,
      discovery,
    });
    return this.cached;
  }

  async discovery(options: { selected?: ModelRef | null; accessMode?: ModelAccessMode } = {}): Promise<OpenCodeDiscovery> {
    if (this.discoveryCache && this.discoveryCache.expiresAt > Date.now()) return this.discoveryCache.discovery;
    const status = await this.check({ selected: options.selected, accessMode: options.accessMode });
    if (!status.discovery) throw new Error("OpenCode discovery is unavailable until the connection succeeds.");
    return status.discovery;
  }

  async resolveModel(
    selection: ModelRef | null,
    discovery?: OpenCodeDiscovery,
    accessMode: ModelAccessMode = "ALL_ACCESSIBLE",
  ): Promise<ModelResolution | null> {
    const current = discovery ?? await this.discovery({ selected: selection });
    if (selection) {
      const match = current.models.find((model) =>
        model.providerID === selection.providerID
        && model.id === selection.id
        && model.availability === "available",
      );
      if (match) {
        assertModelAllowed(match, accessMode);
        if (selection.variant && !match.variants.includes(selection.variant)) {
          throw new Error(`Variant "${selection.variant}" is not reported for ${match.key}.`);
        }
        return { model: match, source: "selected" };
      }
    }
    return null;
  }

  /**
   * Resolve a migrated legacy identity. The legacy model is used only when the
   * current catalog still reports it; this method never substitutes an
   * unrelated or paid model. New projects choose explicitly in onboarding.
   */
  async chooseDefaultModel(legacyModel?: string | null): Promise<ModelResolution | null> {
    if (!legacyModel) return null;
    const discovery = await this.discovery({ selected: null });
    const legacy = discovery.models.find((model) =>
      model.key === legacyModel && model.availability === "available" && isFreeOrLocal(model));
    return legacy ? { model: legacy, source: "legacy" } : null;
  }

  validateSelection(
    discovery: OpenCodeDiscovery,
    model: ModelRef,
    accessMode: ModelAccessMode = "ALL_ACCESSIBLE",
  ): DiscoveredModel {
    const match = discovery.models.find((candidate) =>
      candidate.providerID === model.providerID
      && candidate.id === model.id
      && candidate.availability === "available",
    );
    if (!match) throw new Error(`${model.providerID}/${model.id} is not an available model reported by OpenCode.`);
    assertModelAllowed(match, accessMode);
    if (model.variant && !match.variants.includes(model.variant)) {
      throw new Error(`Variant "${model.variant}" is not reported for ${match.key}. Reported variants: ${match.variants.join(", ") || "none"}.`);
    }
    return match;
  }

  private async persist(): Promise<void> {
    await mkdir(dirname(this.path), { recursive: true });
    const temporary = `${this.path}.tmp-${process.pid}-${Date.now()}`;
    await writeFile(temporary, `${JSON.stringify(this.settings, null, 2)}\n`, { mode: 0o600 });
    await chmod(temporary, 0o600);
    await rename(temporary, this.path);
  }

  private failureStatus(
    baseUrl: string,
    message: string,
    diagnostics: ConnectionStatus["diagnostics"],
    state: ConnectionStatus["state"] = "unavailable",
  ): ConnectionStatus {
    return connectionStatusSchema.parse({
      ...this.initialStatus(),
      state,
      baseUrl,
      checkedAt: this.now().toISOString(),
      diagnostics,
      discovery: null,
      serverVersion: null,
      compatible: null,
    });
  }

  private repairFor(code: string): string {
    if (code === "AUTH_REQUIRED" || code === "PASSWORD_MISMATCH") return "Enter the OpenCode server password (the value printed by `opencode serve`, or OPENCODE_PASSWORD). Provider API keys belong in OpenCode, not here.";
    if (code === "ORIGIN_BLOCKED") return "Check the OpenCode server's hostname, CORS/origin settings, and reverse proxy. This application connects from the server, not the browser.";
    if (code === "TIMEOUT") return "Confirm the OpenCode process is healthy and the URL points at its API port. Retry when it is idle.";
    if (code === "MALFORMED") return "Confirm the URL points at an OpenCode 2.x server (not a different service or a stale proxy).";
    return "Start OpenCode with `opencode serve --hostname 127.0.0.1 --port 4096`, confirm the URL and port, then retry.";
  }

  private diagnosticsFor(discovery: OpenCodeDiscovery, selected: ModelRef | null, accessMode: ModelAccessMode) {
    const diagnostics: ConnectionStatus["diagnostics"] = [];
    if (discovery.server.warning) {
      diagnostics.push({
        code: "VERSION_UNTESTED",
        severity: "warning",
        title: "Untested OpenCode patch version",
        message: discovery.server.warning,
        repair: `Use OpenCode ${discovery.server.testedVersion} for the tested surface, or verify the new version with the live diagnostic.`,
      });
    }
    if (discovery.models.length === 0) {
      diagnostics.push({
        code: "NO_MODELS",
        severity: "error",
        title: "No models reported",
        message: "OpenCode returned no selectable models.",
        repair: "Connect a provider inside OpenCode (`/connect`), then run `/models` or restart the server. This app never asks for provider API keys.",
      });
    }
    const availableModels = discovery.models.filter((model) => model.availability === "available");
    if (discovery.models.length > 0 && availableModels.length === 0) {
      diagnostics.push({
        code: "NO_AVAILABLE_MODELS",
        severity: "error",
        title: "No available models",
        message: "Every model in the catalog is disabled or tied to a disabled provider.",
        repair: "Enable a provider/model inside OpenCode, then retry discovery.",
      });
    }
    for (const provider of discovery.providers.filter((item) => item.ready === "needs_auth")) {
      diagnostics.push({
        code: "PROVIDER_NOT_CONNECTED",
        severity: "warning",
        title: `${provider.name} needs authentication`,
        message: provider.detail,
        repair: `Connect ${provider.name} inside OpenCode with /connect, or choose a model from a provider that is already available.`,
      });
    }
    if (selected) {
      const match = discovery.models.find((model) => model.providerID === selected.providerID && model.id === selected.id);
      if (!match) {
        diagnostics.push({
          code: "MODEL_UNAVAILABLE",
          severity: "error",
          title: "Selected model is unavailable",
          message: `${selected.providerID}/${selected.id} is not in the current OpenCode catalog.`,
          repair: "Choose another model in the OpenCode panel. The previous selection was not replaced automatically.",
        });
      } else if (match.availability !== "available") {
        diagnostics.push({
          code: "MODEL_DISABLED",
          severity: "error",
          title: "Selected model is disabled",
          message: `${match.name} is present but unavailable (${match.status}).`,
          repair: "Enable the model or provider inside OpenCode, or choose another model.",
        });
      } else if (!modelAllowed(match, accessMode)) {
        diagnostics.push({
          code: "MODEL_ACCESS_POLICY_BLOCKED",
          severity: "error",
          title: "Selected model is blocked by the access preference",
          message: `${match.name} reports paid or unknown remote pricing while this project is set to Free and local only.`,
          repair: "Choose a free/local model, or deliberately change Model access to All accessible models. The app will not substitute a model.",
        });
      } else if (selected.variant && !match.variants.includes(selected.variant)) {
        diagnostics.push({
          code: "VARIANT_UNAVAILABLE",
          severity: "error",
          title: "Selected variant is not reported",
          message: `Variant "${selected.variant}" is not attached to ${match.key}. Reported variants: ${match.variants.join(", ") || "none"}.`,
          repair: "Choose a variant reported for this model, or use the model default.",
        });
      }
      if (match?.local && ((match.limits.context ?? 0) < 8_192 || (match.limits.output ?? 0) < 1_024)) {
        diagnostics.push({
          code: "LOCAL_MODEL_LIMITS",
          severity: "warning",
          title: "Local model has small limits",
          message: `${match.name} reports a ${match.limits.context ?? "unknown"} token context and ${match.limits.output ?? "unknown"} token output limit.`,
          repair: "Lower the planned scope, increase the local model context/output in its runtime, or choose a model with larger limits. OpenCode does not report free RAM or VRAM.",
        });
      }
    }
    if (discovery.permissions.length > 0) {
      diagnostics.push({
        code: "PERMISSION_PENDING",
        severity: "warning",
        title: "Permission decisions are waiting",
        message: `${discovery.permissions.length} OpenCode permission request(s) need a human decision.`,
        repair: "Review each request in the OpenCode panel. This application never auto-approves a request.",
      });
    }
    return diagnostics;
  }

  private partialLimitations(results: Record<string, PromiseSettledResult<unknown> | "fulfilled" | "rejected">): string[] {
    const limitations: string[] = [];
    for (const [name, result] of Object.entries(results)) {
      const status = typeof result === "string" ? result : result.status;
      if (status === "rejected") limitations.push(`OpenCode ${name} discovery failed for this version. That section is visibly deferred.`);
    }
    return limitations;
  }
}

function diagnosticWarnings(diagnostics: ConnectionStatus["diagnostics"]): boolean {
  return diagnostics.some((diagnostic) => diagnostic.severity === "warning");
}

function isFreeOrLocal(model: DiscoveredModel): boolean {
  return model.pricing === "free" || model.local === true;
}

function modelAllowed(model: DiscoveredModel, accessMode: ModelAccessMode): boolean {
  return accessMode === "ALL_ACCESSIBLE" || isFreeOrLocal(model);
}

function assertModelAllowed(model: DiscoveredModel, accessMode: ModelAccessMode): void {
  if (modelAllowed(model, accessMode)) return;
  throw new Error("This project is set to Free and local only. Choose a free/local model or deliberately change the model access preference.");
}

export function safeErrorMessage(error: unknown): string {
  return redactSecrets(error instanceof Error ? error.message : String(error));
}

import { spawn } from "node:child_process";
import { resolve } from "node:path";
import { createLogger } from "./observability/logger.ts";

const log = createLogger({ redact: { hideLocalPaths: true } });
const REDACTED = REDACTED;
if (!REDACTED) throw new Error("OPENCODE_PASSWORD is required on Render.");

const port = process.env.OPENCODE_PORT?.trim() || "4096";
const dataHome = process.env.OPENCODE_DATA_HOME?.trim() || "/var/data/xdg-data";
const configHome = process.env.OPENCODE_CONFIG_HOME?.trim() || "/var/data/xdg-config";
const executable = resolve("node_modules/@opencode/cli-linux-x64-baseline/bin/opencode");
const openCode = spawn(executable, ["serve", "--hostname", "127.0.0.1", "--port", port], {
  cwd: process.cwd(),
  stdio: ["ignore", "inherit", "inherit"],
  env: {
    ...process.env,
    OPENCODE_PASSWORD: REDACTED,
    OPENCODE_SERVER_PASSWORD: REDACTED,
    XDG_DATA_HOME: dataHome,
    XDG_CONFIG_HOME: configHome,
  },
});

await import("./instrument.ts");
let server: { close: (callback?: () => void) => void };
try {
  ({ server } = await import("./index.ts"));
} catch (error) {
  log.error("startup_failed", { message: error instanceof Error ? error.message : "unknown startup failure" });
  openCode.kill("SIGTERM");
  process.exit(1);
}
let shuttingDown = false;

function stop(exitCode: number, signal: NodeJS.Signals = "SIGTERM") {
  if (shuttingDown) return;
  shuttingDown = true;
  log.info("render_child_stopping", { signal, exitCode });
  openCode.kill(signal);
  server.close(() => process.exit(exitCode));
  setTimeout(() => process.exit(exitCode), 10_000).unref();
}

process.once("SIGTERM", () => stop(0, "SIGTERM"));
process.once("SIGINT", () => stop(0, "SIGINT"));

openCode.once("error", (error) => {
  log.error("opencode_start_failed", { message: error.message });
  stop(1);
});
openCode.once("exit", (code, signal) => {
  if (shuttingDown) return;
  log.error("opencode_exited", { code: code ?? null, signal: signal ?? null });
  stop(code && code > 0 ? code : 1);
});
import { randomBytes } from "node:crypto";
import { resolve } from "node:path";
import { z } from "zod";
import type { RuntimeConfig } from "../shared/contracts.ts";

/**
 * Canonical deployment modes.
 *
 * `hosted-demo` is a public, read-only deterministic sample with no OpenCode,
 * no credentials, and no session token. `private-hosted` is a protected,
 * persistent instance with OpenCode and Basic Auth. `local` stays loopback.
 */
export const appModeSchema = z.enum(["local", "hosted-demo", "private-hosted"]);
export type AppMode = z.infer<typeof appModeSchema>;

export const runtimeModeSchema = z.enum(["local", "demo", "private-hosted"]);
export type RuntimeMode = z.infer<typeof runtimeModeSchema>;

export function runtimeModeOf(mode: AppMode): RuntimeMode {
  return mode === "hosted-demo" ? "demo" : mode;
}

export class ConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ConfigError";
  }
}

export interface LimitsConfig {
  maxRequestBytes: number;
  rateLimitPerMinute: number;
  maxConcurrentMutations: number;
  maxSseConnections: number;
  guideTimeoutMs: number;
  makerTimeoutMs: number;
  nodeCheckTimeoutMs: number;
  maxSessionTokens: number;
  maxSessionCostUsd: number | null;
}

export interface RetentionConfig {
  actions: number;
  approvals: number;
  operations: number;
  evidence: number;
  transcript: number;
  witnessDrafts: number;
  backups: number;
  corruptFiles: number;
  backupMaxAgeDays: number;
}

export interface OpenCodeConfig {
  baseUrl: string;
  username: string;
  REDACTED: string | undefined;
  allowInsecureRemote: boolean;
  allowedHosts: string[];
  allowedPorts: number[];
  allowPrivateNetwork: boolean;
  requestTimeoutMs: number;
  maxResponseBytes: number;
}

export interface AppConfig {
  mode: AppMode;
  production: boolean;
  hostname: string;
  port: number;
  dataDirectory: string;
  demoWorkspace: string;
  spiritWorkspace: string;
  statePath: string;
  sessionToken: string;
  access: { username: string; REDACTED: string } | null;
  publicUrl: URL | null;
  allowedHosts: string[];
  allowedOrigins: string[];
  trustProxy: boolean;
  opencode: OpenCodeConfig;
  limits: LimitsConfig;
  retention: RetentionConfig;
  redactPrompts: boolean;
  hideLocalPaths: boolean;
}

const loopbackHosts = new Set(["127.0.0.1", "localhost", "::1", "[::1]"]);

export function isLoopbackHost(hostname: string): boolean {
  const normalized = hostname.trim().toLowerCase().replace(/^\[|\]$/g, "");
  return normalized === "localhost" || normalized === "127.0.0.1" || normalized === "::1"
    || normalized.startsWith("127.");
}

function integer(env: NodeJS.ProcessEnv, name: string, fallback: number, min: number, max: number): number {
  const raw = env[name]?.trim();
  if (!raw) return fallback;
  const value = Number(raw);
  if (!Number.isInteger(value) || value < min || value > max) {
    throw new ConfigError(`${name} must be an integer between ${min} and ${max}.`);
  }
  return value;
}

function optionalDecimal(env: NodeJS.ProcessEnv, name: string, max: number): number | null {
  const raw = env[name]?.trim().toLowerCase();
  if (!raw || raw === "unlimited" || raw === "disabled") return null;
  const value = Number(raw);
  if (Number.isFinite(value) && value === 0) return null;
  if (!Number.isFinite(value) || value < 0 || value > max) {
    throw new ConfigError(`${name} must be a positive number up to ${max}, or unlimited/disabled.`);
  }
  return value;
}

function bool(env: NodeJS.ProcessEnv, name: string, fallback = false): boolean {
  const raw = env[name]?.trim().toLowerCase();
  if (!raw) return fallback;
  if (["1", "true", "yes", "on"].includes(raw)) return true;
  if (["0", "false", "no", "off"].includes(raw)) return false;
  throw new ConfigError(`${name} must be true or false.`);
}

function list(value: string | undefined): string[] {
  return (value ?? "")
    .split(",")
    .map((entry) => entry.trim().toLowerCase())
    .filter(Boolean);
}

/**
 * `UB_DEPLOYMENT_MODE` is canonical. `UB_MODE` remains a compatibility alias
 * for the hardening line, which also used `private-hosted` as a spelling.
 */
export function detectMode(env: NodeJS.ProcessEnv = process.env): AppMode {
  const explicit = env.UB_DEPLOYMENT_MODE?.trim() || env.UB_MODE?.trim();
  if (explicit) {
    const normalized = explicit === "hosted-private" || explicit === "private-hosted"
      ? "private-hosted"
      : explicit;
    const parsed = appModeSchema.safeParse(normalized);
    if (!parsed.success) throw new ConfigError("UB_DEPLOYMENT_MODE must be local, hosted-demo, or hosted-private.");
    return parsed.data;
  }
  if (env.RENDER) return "private-hosted";
  if (env.NODE_ENV === "production") return "private-hosted";
  return "local";
}

function parsePublicUrl(raw: string | undefined, mode: AppMode): URL | null {
  const value = raw?.trim();
  if (!value) return null;
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    throw new ConfigError("UB_PUBLIC_URL must be an absolute URL.");
  }
  if (!["http:", "https:"].includes(url.protocol)) throw new ConfigError("UB_PUBLIC_URL must use http or https.");
  if (mode !== "local" && url.protocol !== "https:" && !isLoopbackHost(url.hostname)) {
    throw new ConfigError("UB_PUBLIC_URL must use HTTPS outside loopback.");
  }
  if (url.username || url.REDACTED || url.search || url.hash) {
    throw new ConfigError("UB_PUBLIC_URL must not contain credentials, a query, or a fragment.");
  }
  return url;
}

export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const mode = detectMode(env);
  const production = mode !== "local" || env.NODE_ENV === "production";
  const hostname = env.UB_HOST?.trim() || (mode === "local" ? "127.0.0.1" : "0.0.0.0");
  if (mode === "local" && !isLoopbackHost(hostname)) {
    throw new ConfigError("Local mode must bind to a loopback address. Use UB_DEPLOYMENT_MODE=hosted-demo or hosted-private for a public listener.");
  }

  const ubPort = integer(env, "UB_PORT", 4200, 1, 65_535);
  const port = env.PORT?.trim() ? integer(env, "PORT", ubPort, 1, 65_535) : ubPort;
  const dataDirectory = resolve(env.UB_DATA_DIR?.trim() || ".unfinished-business");
  const demoWorkspace = resolve(dataDirectory, "demo-workspace");
  const spiritWorkspace = resolve(dataDirectory, "spirit-workspace");
  const statePath = resolve(dataDirectory, "project.json");

  const configuredToken = REDACTED;
  if (mode === "private-hosted" && !configuredToken) {
    throw new ConfigError("UB_SESSION_TOKEN is required in private-hosted mode.");
  }
  const sessionToken = REDACTED || randomBytes(32).toString("base64url");

  const REDACTED = REDACTED;
  if (mode === "private-hosted" && !REDACTED) {
    throw new ConfigError("UB_ACCESS_PASSWORD is required in private-hosted mode.");
  }

  const renderHost = env.RENDER_EXTERNAL_HOSTNAME?.trim();
  const publicUrl = parsePublicUrl(
    env.UB_PUBLIC_URL?.trim() || (renderHost ? `https://${renderHost}` : undefined),
    mode,
  );
  if (mode === "private-hosted" && !publicUrl) {
    throw new ConfigError("UB_PUBLIC_URL or RENDER_EXTERNAL_HOSTNAME is required in private-hosted mode so origin checks are explicit.");
  }

  const allowedHosts = new Set([
    ...loopbackHosts,
    ...list(env.UB_ALLOWED_HOSTS),
    ...(publicUrl ? [publicUrl.host.toLowerCase()] : []),
  ]);
  const allowedOrigins = new Set([
    ...(publicUrl ? [publicUrl.origin] : []),
    ...list(env.UB_ALLOWED_ORIGINS),
  ]);

  const opencodeBaseUrl = env.OPENCODE_BASE_URL?.trim() || "http://127.0.0.1:4096";
  try {
    const parsed = new URL(opencodeBaseUrl);
    if (!["http:", "https:"].includes(parsed.protocol) || parsed.username || parsed.REDACTED || parsed.search || parsed.hash) {
      throw new Error("invalid");
    }
  } catch {
    throw new ConfigError("OPENCODE_BASE_URL must be an absolute HTTP(S) URL without credentials, query, or fragment.");
  }
  const allowInsecureRemote = bool(env, "UB_OPENCODE_ALLOW_INSECURE_REMOTE")
    && mode === "local"
    && env.NODE_ENV !== "production";

  return {
    mode,
    production,
    hostname,
    port,
    dataDirectory,
    demoWorkspace,
    spiritWorkspace,
    statePath,
    sessionToken,
    access: REDACTED
      ? {
          username: env.UB_ACCESS_USERNAME?.trim() || "unfinished-business",
          REDACTED: REDACTED,
        }
      : null,
    publicUrl,
    allowedHosts: [...allowedHosts],
    allowedOrigins: [...allowedOrigins],
    trustProxy: mode !== "local" && bool(env, "UB_TRUST_PROXY", true),
    opencode: {
      baseUrl: opencodeBaseUrl,
      username: env.OPENCODE_USERNAME?.trim() || "opencode",
      REDACTED: REDACTED || undefined,
      allowInsecureRemote,
      allowedHosts: list(env.UB_OPENCODE_ALLOWED_HOSTS),
      allowedPorts: list(env.UB_OPENCODE_ALLOWED_PORTS).map((entry) => {
        const value = Number(entry);
        if (!Number.isInteger(value) || value < 1 || value > 65_535) {
          throw new ConfigError("UB_OPENCODE_ALLOWED_PORTS must contain comma-separated port numbers.");
        }
        return value;
      }),
      allowPrivateNetwork: bool(env, "UB_OPENCODE_ALLOW_PRIVATE_NETWORK"),
      requestTimeoutMs: integer(env, "UB_OPENCODE_REQUEST_TIMEOUT_MS", 300_000, 1_000, 900_000),
      maxResponseBytes: integer(env, "UB_OPENCODE_MAX_RESPONSE_BYTES", 8 * 1024 * 1024, 64 * 1024, 64 * 1024 * 1024),
    },
    limits: {
      maxRequestBytes: integer(env, "UB_MAX_REQUEST_BYTES", 64 * 1024, 1_024, 1024 * 1024),
      rateLimitPerMinute: integer(env, "UB_RATE_LIMIT_PER_MINUTE", 120, 1, 10_000),
      maxConcurrentMutations: integer(env, "UB_MAX_CONCURRENT_MUTATIONS", 1, 1, 16),
      maxSseConnections: integer(env, "UB_MAX_SSE_CONNECTIONS", 4, 1, 64),
      guideTimeoutMs: integer(env, "UB_GUIDE_TIMEOUT_MS", 90_000, 5_000, 600_000),
      makerTimeoutMs: integer(env, "UB_MAKER_TIMEOUT_MS", 180_000, 5_000, 900_000),
      nodeCheckTimeoutMs: integer(env, "UB_NODE_CHECK_TIMEOUT_MS", 30_000, 1_000, 300_000),
      maxSessionTokens: integer(env, "UB_MAX_SESSION_TOKENS", 200_000, 1_000, 10_000_000),
      maxSessionCostUsd: optionalDecimal(env, "UB_MAX_SESSION_COST_USD", 100),
    },
    retention: {
      actions: integer(env, "UB_RETENTION_ACTIONS", 500, 50, 100_000),
      approvals: integer(env, "UB_RETENTION_APPROVALS", 200, 20, 10_000),
      operations: integer(env, "UB_RETENTION_OPERATIONS", 200, 20, 10_000),
      evidence: integer(env, "UB_RETENTION_EVIDENCE", 200, 10, 10_000),
      transcript: integer(env, "UB_RETENTION_TRANSCRIPT", 40, 10, 1_000),
      witnessDrafts: integer(env, "UB_RETENTION_WITNESS_DRAFTS", 10, 1, 100),
      backups: integer(env, "UB_BACKUP_COUNT", 3, 1, 20),
      corruptFiles: integer(env, "UB_CORRUPT_FILE_COUNT", 5, 1, 50),
      backupMaxAgeDays: integer(env, "UB_BACKUP_MAX_AGE_DAYS", 30, 1, 3_650),
    },
    redactPrompts: bool(env, "UB_REDACT_PROMPTS"),
    hideLocalPaths: mode !== "local" || bool(env, "UB_REDACT_LOCAL_PATHS"),
  };
}

export function publicRuntimeConfig(config: AppConfig): RuntimeConfig {
  return {
    mode: config.mode,
    production: config.production,
    demoWorkspace: true as const,
    authRequired: Boolean(config.access),
    originProtection: true as const,
