.site-header,
.workshop-header {
  position: sticky;
  top: 0;
  z-index: 60;
  border-bottom: 1px solid var(--border);
  background: rgb(5 7 13 / 78%);
  backdrop-filter: blur(18px) saturate(1.2);
}

.site-header-inner,
.workshop-header-inner {
  display: flex;
  align-items: center;
  gap: var(--space-5);
  width: min(1240px, calc(100% - 2rem));
  min-height: 72px;
  margin: 0 auto;
}

.site-nav {
  display: flex;
  align-items: center;
  gap: 0.2rem;
  margin-left: auto;
  overflow-x: auto;
  scrollbar-width: none;
}

.site-nav::-webkit-scrollbar { display: none; }

.site-nav a,
.workshop-header-actions a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  padding: 0 0.7rem;
  border-radius: var(--radius-pill);
  color: var(--text-muted);
  font-size: 0.88rem;
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
}

.site-nav a:hover,
.workshop-header-actions a:hover {
  background: rgb(240 235 225 / 6%);
  color: var(--text);
}

.site-header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-left: auto;
}

.site-header-actions .action { white-space: nowrap; }

.workshop-header-inner { justify-content: space-between; }

.workshop-header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.engine-pill {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  min-height: 40px;
  padding: 0 0.8rem;
  border: 1px solid var(--border);
}

@media (max-width: 960px) {
  .site-nav { display: none; }
  .demo-intro { grid-template-columns: minmax(0, 1fr); }
  .demo-main-card { grid-template-columns: minmax(0, 1fr); }
  .demo-main-art { min-height: 260px; border-right: 0; border-bottom: 1px solid var(--border); }
  .state-gallery { grid-template-columns: minmax(0, 1fr); }
  .frame { grid-template-columns: minmax(0, 1fr); }
  .side { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .inspector-side { grid-template-columns: minmax(0, 1fr); }
  .outline-panel { order: 2; }
  .engine-panel { order: 1; }
  .activity-grid { grid-template-columns: minmax(0, 1fr); }
  .activity-section + .activity-section { border-left: 0; border-top: 1px solid var(--border); }
  .memory-groups { grid-template-columns: minmax(0, 1fr); }
  .technical-grid { grid-template-columns: minmax(0, 1fr); }
}

@media (max-width: 720px) {
  .site-header-inner,
  .workshop-header-inner {
    flex-wrap: wrap;
    gap: var(--space-2) var(--space-3);
    width: min(100% - 1.25rem, 1240px);
    min-height: 64px;
    padding-block: var(--space-2);
  }

  .demo-header .text-link { display: none; }
  .brand-tag { display: none; }
  .site-header-actions .text-button { display: none; }
  .site-header-actions .action { min-height: 40px; padding: 0.55rem 0.85rem; font-size: 0.82rem; }
  .workshop-header-actions a { display: none; }
  .engine-pill { padding: 0 0.6rem; font-size: 0.7rem; }
  .header-model-inline,
  .header-controls-label { display: none; }
  .workshop-header-actions { gap: var(--space-1); }
  .compact-titlebar { min-height: 0; padding: var(--space-2) 0; }
  .workshop-title-actions .workshop-character { width: 70px; }
  .focused-document { margin-top: var(--space-3); }
  .workshop-drawer > summary { padding-inline: var(--space-3); }
  .workshop-drawer-body { padding: var(--space-3); }
  .permission-banner { flex-wrap: wrap; }
  .permission-banner .action { width: 100%; }
  .activity-drawer .inspector-head { display: grid; }
  .technical-details { margin-inline: var(--space-3); }
  .memory-editor-head { flex-direction: column; }

  .hero {
    width: calc(100% - 1rem);

